parameters.jsCode:
const body = $json.body || $json;
const alertType = body.alertType || body.event || 'UNKNOWN';
const monitorName = body.monitorFriendlyName || body.monitorName || 'Alo Yönetim Web';
const monitorUrl = body.monitorURL || 'https://aloyonetim.com.tr';
const alertDetails = body.alertDetails || 'Ayrıntı yok';
const isDown = String(alertType).toLowerCase().includes('down');

return [{
  json: {
    timestamp: new Date().toISOString(),
    isDown,
    severity: isDown ? 'CRITICAL' : 'RECOVERED',
    monitorName,
    monitorUrl,
    alertDetails,
    subject: isDown ? '🚨 [DIŞ KESİNTİ] Alo Yönetim Yanıt Vermiyor!' : '✅ [DÜZELDİ] Alo Yönetim Tekrar Yayında',
    summary: `UptimeRobot Olayı: ${isDown ? 'SİTE ÇÖKTÜ' : 'SİTE AÇILDI'} (${monitorName} - ${monitorUrl})`
  }
}];

